function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100) return 'nums needs 2 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each value is a whole number from 0 to 100.';
  return null;
}

