function orArray(nums) {
  // Rebuild each OR one bit at a time, without the | operator.
  const result = [];
  for (let i = 1; i < nums.length; i++) {
    let a = nums[i - 1], b = nums[i], value = 0;
    for (let bit = 1; a > 0 || b > 0; bit *= 2) {
      if (a % 2 === 1 || b % 2 === 1) value += bit;
      a = Math.floor(a / 2);
      b = Math.floor(b / 2);
    }
    result.push(value);
  }
  return result;
}

