function generate(rand, size) {
  const n = size === 'large' ? 100 : 2 + Math.floor(rand() * 7);
  const pick = () => {
    const r = rand();
    if (r < 0.15) return 0;
    if (r < 0.25) return 100;
    if (r < 0.45) return 2 ** Math.floor(rand() * 7);
    return Math.floor(rand() * 101);
  };
  return [Array.from({ length: n }, pick)];
}
